changeSet.sql:
ALTER TABLE price_tiers ADD COLUMN tier_type varchar(16) NOT NULL DEFAULT 'LAND_SIZE';

COMMENT ON COLUMN price_tiers.tier_type IS
    'LAND_SIZE (a size band) or UNIT_TYPE (a built-unit product). For UNIT_TYPE, size_sqm is null and `label` carries the meaning — no extra column is needed.';

ALTER TABLE price_tiers ADD CONSTRAINT chk_price_tiers_tier_type
    CHECK (tier_type IN ('LAND_SIZE', 'UNIT_TYPE'));

ALTER TABLE price_tiers ALTER COLUMN size_sqm DROP NOT NULL;

COMMENT ON COLUMN price_tiers.size_sqm IS
    'The NOMINAL size this tier represents — what its plots are sold and priced as, not what any survey at. Nullable since a UNIT_TYPE tier is discriminated by product, not square metres; chk_price_tiers_land_size_has_size requires it whenever tier_type = LAND_SIZE, where its absence would be meaningless.';

-- A LAND_SIZE tier without a size is meaningless. A UNIT_TYPE
-- tier does not NEED one, but is not forbidden from having one
-- (a built unit can sit on a known land area).
ALTER TABLE price_tiers ADD CONSTRAINT chk_price_tiers_land_size_has_size
    CHECK (tier_type <> 'LAND_SIZE' OR size_sqm IS NOT NULL);
